#include <iostream>
#include <algorithm>
#include <iterator>
#include <numeric>
#include <vector>

int main() {
    int n, threshold;
    if (!(std::cin >> n >> threshold) || n < 0 || n > 64 ||
        threshold < -10000 || threshold > 10000) {
        std::cout << "invalid\n";
        return 0;
    }
    std::vector<int> source;
    for (int i = 0; i < n; ++i) {
        int value;
        if (!(std::cin >> value) || value < -10000 || value > 10000) {
            std::cout << "invalid\n";
            return 0;
        }
        source.push_back(value);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) {
        std::cout << "invalid\n";
        return 0;
    }

    std::vector<int> selected;
    // TODO: Перенесите в selected значения, которые не меньше threshold.
    // TODO: Отсортируйте выбранные значения по убыванию и удвойте их.
    const auto sum = std::accumulate(selected.begin(), selected.end(), 0LL);
    std::cout << selected.size() << ' ' << sum << '\n';
    for (std::size_t i = 0; i < selected.size(); ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << selected[i];
    }
    std::cout << '\n';
}
